const originalRender=render;
function navigateTo(next){view=next;render()}
function islandInfo(w){$('#gamebody').innerHTML=`<div class="eyebrow">VÙNG ĐẤT SẮP RA MẮT</div><h2>${worlds[w][2]} ${worlds[w][0]}</h2><p>${worlds[w][1]}</p><p>${w===2?'Những chú robot đang chuẩn bị thử thách sắp xếp lệnh và sửa thuật toán.':'Những vụ án nhỏ sẽ giúp em học cách so sánh bằng chứng và phát hiện mâu thuẫn.'}</p><div class="tutor">Hòn đảo này đang được xây dựng. Em có thể khám phá Rừng Quy Luật và Lâu Đài Suy Luận ngay hôm nay!</div><button class="btn" onclick="document.querySelector('#game').close();play(0)">Khám phá Rừng Quy Luật →</button>`;$('#game').showModal()}
render=function(){originalRender();document.body.classList.toggle('island-mode',view==='map');if(view!=='map')return;$('#content').innerHTML=`<section class="gameworld" aria-label="Bản đồ bốn hòn đảo tư duy"><div class="mapviewport" tabindex="0" aria-label="Bản đồ có thể cuộn ngang trên điện thoại"><div class="mapcanvas"><div class="map-heading"><span>CHÀO MỪNG ĐẾN VỚI</span><h1>Quần đảo tư duy</h1><p>Chọn một hòn đảo. Bắt đầu một điều kỳ diệu.</p></div>${worlds.map((w,i)=>`<button class="island-hotspot island-${i} ${i>1?'upcoming':''}" onclick="${i<2?`play(${i})`:`islandInfo(${i})`}" aria-label="${i<2?'Chơi':'Xem thông tin'} ${w[0]}"><span class="island-number">${i<2?'✦':'🔒'} ${String(i+1).padStart(2,'0')}</span><span class="island-name">${w[0]}</span><span class="island-caption">${i<2?`${count(i)}/4 thử thách · ${count(i)===4?'Chơi lại':'Vào khám phá'} →`:'Đang xây dựng'}</span>${i<2?`<span class="island-progress"><i style="width:${count(i)*25}%"></i></span>`:''}</button>`).join('')}<span class="map-spark spark-one">✧</span><span class="map-spark spark-two">✦</span></div></div><div class="game-topbar"><div class="player-card"><span class="player-face">🦊</span><div><b>Nhà thám hiểm nhỏ</b><small>Lớp ${state.grade} · ${state.completed.length}/8 thử thách</small><span class="xp-track"><i style="width:${state.completed.length/8*100}%"></i></span></div></div><div class="game-resources"><span>⭐ <b>${stars()}</b> <small>sao</small></span><span>🧭 <b>${state.completed.length}</b><small>/ 8 khám phá</small></span></div><button class="round-game-btn" onclick="navigateTo('parent')" aria-label="Góc phụ huynh">⚙</button></div><div class="quest-note"><span>📜</span><div><b>Nhiệm vụ của em</b><small>${state.completed.length===8?'Em đã khám phá mọi thử thách!':'Ghé thăm một hòn đảo và giải câu đố.'}</small></div></div><div class="game-bottom"><div class="game-logo">Logic<span>Quest</span><small>PHIÊU LƯU TƯ DUY</small></div><nav class="game-dock" aria-label="Điều hướng trò chơi"><button class="selected" onclick="navigateTo('map')"><span>🏝️</span>Bản đồ</button><button onclick="navigateTo('progress')"><span>🧭</span>Hành trình</button><button onclick="navigateTo('badges')"><span>🏆</span>Huy hiệu</button><button onclick="navigateTo('parent')"><span>🏡</span>Phụ huynh</button></nav><button class="owl-help" onclick="mapHelp()" aria-label="Hướng dẫn chơi"><span>🦉</span><b>Cú Mèo</b></button></div><div class="mobile-map-tip">↔ Vuốt ngang để khám phá các đảo</div></section>`;};
function mapHelp(){$('#gamebody').innerHTML='<div class="eyebrow">CÚ MÈO ĐỒNG HÀNH</div><h2>Chào nhà thám hiểm! 🦉</h2><p>Bấm vào tên hòn đảo để bắt đầu chơi. Quan sát câu đố, chọn đáp án và bấm kiểm tra.</p><p>Nếu gặp khó, em có thể nhờ mình gợi ý tối đa 3 lần. Tự giải được câu đố sẽ giúp em nhận nhiều sao hơn!</p><p>Hai đảo Robot và Thám Tử đang được xây dựng. Tiến độ được lưu trên trình duyệt này.</p><button class="btn" onclick="document.querySelector(\'#game\').close()">Mình hiểu rồi!</button>';$('#game').showModal()}
render();
